      "type": "mc",
      "text": "Chris constructed the brick on the picture using red and blue cubes of the\nsame size. The outside of the brick is completely red, but all cubes used inside\nare blue. How many blue cubes did Chris use?",
      "image": "images/ikmc/g3_de5_q09.png",
