      "text": "Part C : Each correct answer is worth 5 points.\nThe picture below shows 9 pencils and a weight of 30 g on a balance scale. The\npicture on the right shows one of the same pencils, a pen, and a weight of 15 g.\nBoth scales are balanced. How many grams does the pen weight?",
