      "explanation": "Phân tích vị trí 5 ngôi nhà đánh số từ 1 đến 5 trên phố:\n- Ngôi nhà xanh dương (Blue) và vàng (Yellow) mang số chẵn, tức là ở số 2 và số 4. Nhà số 3 không thể là Blue hoặc Yellow.\n- Ngôi nhà màu đỏ (Red) chỉ đứng cạnh duy nhất ngôi nhà xanh dương. Ngôi nhà chỉ có 1 nhà bên cạnh phải ở hai đầu dãy: số 1 hoặc số 5.\n  + Nếu Red ở số 1 thì Blue ở số 2.\n  + Nếu Red ở số 5 thì Blue ở số 4.\n- Ngôi nhà xanh dương nằm giữa nhà màu xanh lá (Green) và nhà màu đỏ (Red):\n  + Nếu Red ở số 1, Blue ở số 2 thì Green phải ở số 3.\n  + Nếu Red ở số 5, Blue ở số 4 thì Green phải ở số 3.\nTrong cả hai trường hợp, ngôi nhà số 3 chắc chắn là ngôi nhà màu xanh lá (Green).\nĐáp án đúng: E."
