      "text": "The first three figures of a pattern are constructed from triangles, as shown:\nThere is one triangle on the first figure, 4 triangles on the second figure, and 9\ntriangles on the third figure. If the paZern is extended with several more figures,\nhow many triangles will be there on the fiQh figure?",
