      "number": 3,
      "points": 3,
      "type": "mc",
      "text": "Bố treo 4 chiếc khăn mặt trên một chiếc dây phơi. Bố muốn dùng càng ít chiếc\nkẹp càng tốt. Với 3 chiếc khăn mặt, bố cần 4 chiếc kẹp. Hỏi bố cần bao nhiêu\nchiếc kẹp nếu muốn treo 11 chiếc khăn mặt?",
