      "explanation": "Quy luật dùng kẹp để phơi khăn sao cho tiết kiệm nhất là treo các chiếc khăn liền kề chung kẹp ở mép:\n- 1 chiếc khăn cần: 2 chiếc kẹp (ở 2 đầu).\n- 2 chiếc khăn cần: 2 + 1 = 3 chiếc kẹp (1 kẹp chung ở giữa).\n- 3 chiếc khăn cần: 3 + 1 = 4 chiếc kẹp (đúng như đề bài đã cho).\nQuy luật tổng quát: Số kẹp cần dùng = (Số khăn mặt) + 1.\nDo đó, để treo 11 chiếc khăn mặt, bố cần dùng số chiếc kẹp là:\n  11 + 1 = 12 (chiếc kẹp).\nĐáp án đúng: B."
