      "text": "Frank made a domino snake of seven tile s. He put the tiles next to each\nother so that the sides with the same number of dots touch ed . Originally the\nsnake had 33 dots on its back. However, Frank's brother George took away two\ntiles from the snake (see the picture).\nHow many dots were in the place with the question mark?",
      "image": "images/ikmc/g3_de6_q21.png",
