      "text": "Basil has several domino tiles, as shown in the figure. He wants to arrange\nthem in a line according t o the well-known \"domino rule\": in any two tiles that\nare next to each other, the squares that touch must have the same number of\npoints. What is the largest number of tiles he can arrange in this way?",
      "image": "images/ikmc/g3_de7_q20.png",
