      "explanation": "Tom viết liên tiếp các số từ 1 đến 20 thành một hàng:\n1234567891011121314151617181920\nDãy số này có tổng cộng 9 + 11 × 2 = 31 chữ số.\nTom xóa đi 24 chữ số để lại đúng 7 chữ số tạo thành số lớn nhất có thể (giữ nguyên thứ tự các chữ số):\n- Để được số lớn nhất, chữ số đầu tiên phải là chữ số lớn nhất có thể chọn được: đó là chữ số 9 (ở vị trí số 9). Khi chọn chữ số 9 này, ta đã xóa 8 chữ số đầu tiên (1 đến 8).\n- Còn lại dãy: 1011121314151617181920 (gồm 22 chữ số), ta cần chọn tiếp 6 chữ số lớn nhất.\n- Chữ số thứ hai chọn chữ số 7 của số 17 (để lại các số sau đủ chữ số).\n- Tiếp theo chọn chữ số 8 của số 18.\n- Sau đó chọn chữ số 1 và 9 của số 19, rồi 2 và 0 của số 20.\n- Kết quả thu được số lớn nhất gồm 7 chữ số là: 9781920.\nĐáp án đúng: C (9781920)."
