      "number": 13,
      "points": 4,
      "type": "mc",
      "text": "Peter went hiking in the mountains for 5 days. He started on Monday and his\nlast trip was on Friday. Each day he walked 2km more than the day before. The\ntotal distance he walked during the five days was 70km. What distance did Peter\nwalk on Thursday?",
      "image": null,
      "options": [
        "A. 12 km",
        "B. 13 km",
        "C. 14 km",
        "D. 15 km",
        "E. 16 km"
      ],
