      "text": "Ala likes even numbers, Beata likes numbers divisible by 3, Celina likes\nnumbers divisible by 5. Each of these three girls went separately to a basket\ncontaining 8 balls with numbers written on them, and took all the balls with\nnumbers she liked. It turned out that Ala collected balls with numbers 32 and 52,\nBeata ‐ 24, 33 and 45, Celina ‐ 20, 25 and 35. In what order did the girls\napproach the basket?",
