      "text": "The numbers 1, 2, 3, 4, and 5 must be written in the five cells in the figure,\nrespecting the following rules:\n- If a number is just below another number, it must be greater.\n- If a number is just to the right of another number, it must be greater. In how\nmany ways can this be done?",
