      "explanation": "Năm ô vuông tạo thành hình chữ L gồm ô góc trên cùng bên trái (0,0), hai ô bên phải (0,1), (0,2) và hai ô bên dưới (1,0), (2,0).\nQuy tắc:\n- Ô ở dưới lớn hơn ô ngay phía trên: ô (0,0) < ô (1,0) < ô (2,0).\n- Ô ở bên phải lớn hơn ô ngay bên trái: ô (0,0) < ô (0,1) < ô (0,2).\n- Do ô góc (0,0) nhỏ hơn cả hai nhánh nên bắt buộc ô (0,0) phải điền số nhỏ nhất, tức là số 1.\n- Còn lại 4 số {2, 3, 4, 5} để điền vào 2 ô hàng ngang và 2 ô cột dọc.\n- Số cách chọn 2 số trong 4 số để điền vào nhánh hàng ngang là: C(4, 2) = (4 × 3) / 2 = 6 (cách).\n- Sau khi chọn 2 số cho hàng ngang, thứ tự của chúng được xếp duy nhất theo thứ tự tăng dần từ trái sang phải. Hai số còn lại điền vào nhánh cột dọc cũng được xếp duy nhất theo thứ tự tăng dần từ trên xuống dưới.\n- Vậy có tất cả 6 cách điền thỏa mãn đề bài.\nĐáp án đúng: D (6)."
