      "explanation": "Chu vi của hình chữ nhật ABCD là 30 cm.\nBa hình chữ nhật nhỏ khác được vẽ sao cho tâm của chúng nằm tại ba đỉnh A, B, D của hình chữ nhật lớn và các cạnh song song với cạnh ABCD.\n- Tổng chu vi của 3 hình chữ nhật nhỏ bằng 20 cm.\n- Đường viền đậm dày bên ngoài bao quanh hình được tạo thành bởi các cạnh của ABCD và các đoạn viền của các hình chữ nhật nhỏ.\n- Chu vi của hình đậm bên ngoài bằng: Chu vi(ABCD) + 1/2 × [Tổng chu vi 3 hình chữ nhật nhỏ] = 30 + 20 / 2 = 40 cm.\nĐáp án đúng: C (40 cm)."
