      "number": 23,
      "points": 5,
      "type": "mc",
      "text": "Clara wants to construct a big triangle using identical small triangular tiles.\nShe has already put some tiles together as shown in the picture.\nWhat is the minimum number of additional tiles required to complete a triangle?",
