      "number": 25,
      "points": 5,
      "type": "mc",
      "text": "The symbols,\n, and\ndigits of the three-digit number\nrepresent three different digits. If you add the\n, the result is the two-digit number . If\nyou add the digits of the two-digit number\nnumber\n4\n5\n6",
      "image": "images/ikmc/g5_de3_q25.png",
