      "number": 17,
      "points": 4,
      "type": "mc",
      "text": "The points A , B , C , D , E and F lie on a straight line in that order. We know\nthat AF = 35, AC = 12, BD = 11, CE = 12 and DF = 16. What is the distance BE?",
