      "text": "A plane takes off from Vienna at 11:00 am local time and arrives in Toronto\nat 1:00 pm local time. On average, it takes 8 hours for a plane of this type to fly\nthis distance. What time is it in Toronto when it is 7:00 am in Vienna?",
