      "explanation": "Một chuyến bay cất cánh từ Vienna lúc 11:00 sáng theo giờ địa phương Vienna.\n- Chuyến bay kéo dài 8 giờ, nên khi máy bay hạ cánh tại Toronto thì giờ địa phương tại Vienna là:\n  11:00 + 8:00 = 19:00 (tức 7:00 tối).\n- Khi hạ cánh, đồng hồ ở Toronto chỉ 1:00 chiều (13:00).\n- Chênh lệch múi giờ giữa Vienna và Toronto là:\n  19:00 - 13:00 = 6 giờ (giờ Toronto chậm hơn giờ Vienna 6 tiếng).\n- Khi máy bay cất cánh từ Vienna lúc 7:00 sáng hôm đó, giờ ở Toronto là:\n  7:00 sáng - 6 giờ = 1:00 sáng (1:00 am).\nĐáp án đúng: B (1:00 am)."
