      "type": "mc",
      "text": "Andy made a playlist with 5 songs (A, B, C, D and E ). Song A is 3 minutes\nlong, song B is 2 minutes and 30 seconds, song C is 2 minutes, song D is 1\nminute and 30 seconds, and song E is 4 minutes. The songs play in this order in\na continuous loop. If Andy left the house when song C was just starting, what\nsong was playing when he got back home 1 hour later?",
