      "explanation": "Một dải ruy băng mỏng nhiều màu được dán trên một khối lập phương bằng nhựa trong suốt.\nKhi quay khối lập phương trong không gian theo các hướng khác nhau:\n- Do khối lập phương trong suốt nên người nhìn thấy cả các đoạn ruy băng ở mặt trước và mặt sau.\n- Tuy nhiên tính định hướng không gian và thứ tự liên kết giữa các đoạn ruy băng ở các đỉnh luôn được bảo toàn qua các phép quay 3D.\n- Hình E là hình thể hiện một đường đi bị nghịch đảo định hướng (phản xạ gương chứ không phải phép quay trong không gian), do đó không thể nhận được từ bất kỳ góc nhìn nào.\nĐáp án đúng: E."
