      "points": 5,
      "type": "mc",
      "text": "Trong 3 ngày, chú mèo Joy đang bắt chuột. Mỗi ngày chú bắt được nhiều\nhơn ngày trước 2 con. Vào ngày thứ 3, Joy bắt được số chuột nhiều hơn ngày\nthứ nhất 2 lần. Hỏi tổng cộng Joy bắt được bao nhiêu con chuột trong 3 ngày?",
