      "number": 21,
      "points": 5,
      "type": "mc",
      "text": "Alice có 3 mẩu giấy màu trắng, 2 mẩu màu đen và 2 mẩu màu xám. Sau đó\nAlice cắt tất cả các tờ giấy không phải màu đen ra làm đôi. Tiếp tục, lại cắt tất cả\ncác mẩu giấy không phải màu trắng ra làm đôi. Hỏi khi đó Alice có tất cả bao\nnhiêu mẩu giấy?",
      "image": "images/ikmc/g1_de4_q21.png",
      "options": [
        "A. 14",
        "B. 16",
        "C. 17",
        "D. 18",
        "E. 20"
      ],
