      "number": 23,
      "points": 5,
      "type": "mc",
      "text": "Quãng đường từ nhà Anna tới nhà Mary dài 16 km.\nTừ nhà Mary tới nhà John dài 20 km.\nTừ ngã ba đường tới nhà Mary dài 9 km.\nHỏi từ nhà Anna tới nhà John dài bao nhiêu km?\n7 km",
      "image": "images/ikmc/g1_de4_q23.png",
