      "number": 22,
      "points": 5,
      "type": "mc",
      "text": "Để có tích của phép tính 2 x 3 x 15, Bill phải nhấn các phím trên máy tính\ncủa bạn ấy 7 lần như sau:\n.\nBill muốn nhân tất cả các con số từ 3 tới 21, bằng cách sử dụng chiếc máy tính\ntrên. Hỏi ít nhất Bill phải bấm bao nhiêu lần?",
